CREATE TABLE [dbo].[TREC_PARAMETROS](	  [par_id] SMALLINT NOT NULL	, [par_descripcion] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [par_valor] VARCHAR(600) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [par_detail] VARCHAR(500) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, CONSTRAINT [PK_TREC_PARAMETROS] PRIMARY KEY ([par_id] ASC))